    @if($cycle->status !== 'completed' && $canCompleteEntireCycle)<form method="post" action="{{ route('inventory.complete', $cycle) }}" class="completion">@csrf<strong>Οριστικοποίηση απογραφής</strong><div class="muted">Με την οριστικοποίηση, κάθε αναμενόμενο πάγιο που δεν σαρώθηκε θα καταχωριστεί ως «Δεν βρέθηκε» και δεν θα επιτρέπονται νέες σαρώσεις.</div><label><input type="checkbox" name="confirmation" value="1" required> Επιβεβαιώνω ότι έχω ελέγξει τις αποκλίσεις.</label><button type="submit">Οριστικοποίηση απογραφής</button></form>@elseif($cycle->status !== 'completed')<div class="completion"><strong>Η οριστικοποίηση δεν είναι διαθέσιμη</strong><p class="muted">Μπορείτε να σαρώσετε τα πάγια της αρμοδιότητάς σας, αλλά το κλείσιμο απαιτεί χρήστη με πρόσβαση σε όλα τα πάγια της απογραφής.</p></div>@else<div class="completion"><span class="status">Ολοκληρωμένη</span><p>Η απογραφή έχει οριστικοποιηθεί και δεν δέχεται νέες σαρώσεις.</p></div>@endif
